(function(){const T=window.TABLES_EXTRA=window.TABLES_EXTRA||{};T.oneshot=(T.oneshot||[]).concat([{"n": "Город, который забыл своё имя", "lvl": "11–12", "hook": "Столица соседнего королевства исчезла с карт, а её жители не помнят, кто они. Королевский архивариус просит вернуть городу имя.", "scenes": ["Улицы, где таблички пусты и люди путают лица", "Библиотека, в которой книги стирают сами себя", "Склеп основателя под ратушей, где спит пожиратель имён"], "twist": "Пожирателя призвал сам архивариус, чтобы стереть преступление своего предка; вернув имя, герои вернут и память о нём.", "reward": "Право на имение в столице, 5000 зм, редкий предмет «Перо истинных имён»."}, {"n": "Война двух небес", "lvl": "11–13", "hook": "Над долиной сошлись летающие крепости двух магических орденов; их сражение рушит поля и деревни. Местные просят остановить бой.", "scenes": ["Переправа на крепость на грифонах под обстрелом", "Переговоры с магистром, уверенным в своей правоте", "Сердце-кристалл, удерживающий крепость в воздухе"], "twist": "Оба ордена служат одной и той же древней силе, стравливающей их ради кристаллов.", "reward": "По одному редкому предмету от каждого ордена, грифон-скакун."}, {"n": "Суд над драконом", "lvl": "11–14", "hook": "Взрослый медный дракон обвинён в сожжении города и сам просит героев быть его защитниками на суде.", "scenes": ["Расследование на пепелище: следы и свидетели", "Суд перед советом лордов и толпой", "Охота на настоящего поджигателя — красного дракона-оборотня"], "twist": "Обвинитель-лорд заключил сделку с красным драконом: город сожгли ради шахт под ним.", "reward": "Дракон-должник, сокровище 6000 зм, очень редкий предмет."}, {"n": "Последний поезд ветра", "lvl": "11–12", "hook": "Магический караван-ветроход везёт посла через пустыню; на борту — убийца, а снаружи — песчаная буря и пустынные гиганты.", "scenes": ["Знакомство с пассажирами и первое тело", "Нападение песчаных гигантов на ходу", "Разоблачение в машинном отсеке, где сердце-элементаль рвётся на свободу"], "twist": "Убийца — сам посол, инсценирующий покушение, чтобы начать войну.", "reward": "4000 зм, благодарность двух держав, редкое кольцо."}, {"n": "Кузница богов", "lvl": "12–14", "hook": "В жерле вулкана проснулась легендарная кузница, и каждое рождённое в ней оружие ищет хозяина-тирана.", "scenes": ["Восхождение сквозь лавовые потоки и огненных элементалей", "Встреча с огненным великаном-кузнецом, потерявшим разум", "Горн, который нужно потушить или обуздать"], "twist": "Кузница — тюрьма для забытого бога войны; потушив горн, его освободят.", "reward": "Оружие +2 на выбор, 5000 зм, вражда или дружба божества."}, {"n": "Город под стеклом", "lvl": "12–13", "hook": "Целый город накрыт хрустальным куполом, внутри время течёт в 10 раз быстрее. Изнутри просят помощи — прошло уже 30 лет.", "scenes": ["Проход сквозь купол и старение на годы", "Город, где выросло новое поколение с новой религией", "Механизм купола и его безумный создатель"], "twist": "Создатель держит купол, чтобы успеть найти лекарство от смертельной для всех болезни.", "reward": "Свитки 6–7 круга, лекарство как сюжетный ключ, 4000 зм."}, {"n": "Пир у короля фей", "lvl": "11–13", "hook": "Короля фей пригласили на свадьбу смертного принца, а он прислал приглашение героям: они станут судьями турнира.", "scenes": ["Турнир загадок и поединков в волшебном лесу", "Интрига: невеста — подменыш", "Поединок с рыцарем зимы в полночь"], "twist": "Принц сам пожелал жениться на фее и устроил подмену, но тем самым обрекает королевство на вечную зиму.", "reward": "Дар фей (благословение), очень редкий предмет, долг короля фей."}, {"n": "Затонувшая империя", "lvl": "12–15", "hook": "Отлив, бывающий раз в столетие, обнажил шпили утонувшей столицы. До прилива — 12 часов.", "scenes": ["Гонка мародёров по скользким крышам", "Дворец, где живые тени жителей повторяют последний день", "Тронный зал, где спит морской ужас"], "twist": "Империя утонула не случайно: её правитель принёс её в жертву ради бессмертия — и он всё ещё жив.", "reward": "Сокровище 8000 зм, трезубец (очень редкий), карта к другим руинам."}, {"n": "Собор, который молится сам", "lvl": "13–15", "hook": "Великий собор начал читать молитвы без жрецов, и каждый вошедший становится его прихожанином навсегда.", "scenes": ["Паломники с пустыми глазами у врат", "Лабиринт нефов, где витражи оживают", "Алтарь с пробудившимся небожителем, потерявшим веру"], "twist": "Небожитель жаждет вернуть веру и выбирает героев своими пророками.", "reward": "Святой реликварий (очень редкий), 5000 зм, благословение."}, {"n": "Охота на охотника", "lvl": "13–14", "hook": "Легендарный охотник-ракшас выбрал героев своей дичью и дал им сутки форы.", "scenes": ["Бегство через леса, полные ловушек", "Засада у переправы с наёмниками", "Охотничий замок, где трофеи — прежние герои"], "twist": "Чтобы убить ракшаса навсегда, нужно ударить его же стрелой, которую он хранит у сердца.", "reward": "Трофеи замка: 7000 зм, лук +2, плащ невидимости."}, {"n": "Ключ от тюрьмы титанов", "lvl": "14–16", "hook": "Глубинная секта ищет последний кусок ключа от тюрьмы титана. Он спрятан в теле героя — оставшийся след древнего заклятия.", "scenes": ["Бегство от ассасинов секты", "Поиск мудреца, знающего, как вынуть ключ", "Темница титана, где секта начинает ритуал"], "twist": "Ключ можно уничтожить, только открыв дверь на миг — и встретиться с титаном лицом к лицу.", "reward": "Сила титана как благодать, очень редкий предмет, 9000 зм."}, {"n": "Королева зеркал", "lvl": "13–15", "hook": "Отражения жителей стали жить своей жизнью и по ночам заменяют оригиналы. В столице половина двора уже двойники.", "scenes": ["Пир, на котором нужно вычислить двойников", "Вход в Зазеркалье через огромное зеркало дворца", "Зеркальный трон королевы-отражения"], "twist": "Королева — отражение настоящей правительницы, которую та когда-то предала.", "reward": "Зеркало-портал (очень редкое), титул, 6000 зм."}, {"n": "Чума мёртвых богов", "lvl": "14–16", "hook": "Из земли пробиваются ростки, превращающие людей в статуи. Это кровь давно мёртвого бога.", "scenes": ["Деревни каменных людей", "Кладбище богов на астральном острове", "Сердце бога, которое ещё бьётся"], "twist": "Убить сердце — значит уничтожить последнего, кто помнит лучшее в мире; можно его излечить.", "reward": "Божественный осколок (легендарный компонент), 8000 зм."}, {"n": "Дуэль архимагов", "lvl": "14–15", "hook": "Два архимага поспорили, чья школа сильнее, и поле их дуэли — целое княжество.", "scenes": ["Деревни, где сменяются времена года каждую минуту", "Башня первого мага, полная ловушек", "Башня второго и выбор, на чью сторону встать"], "twist": "Оба мага — один человек, расколотый древним заклинанием.", "reward": "Книга заклинаний с 1к4 заклинаниями 7 круга, посох (очень редкий)."}, {"n": "Сон спящего великана", "lvl": "15–16", "hook": "Каменный великан размером с гору спит, и его кошмары воплощаются вокруг. Если он проснётся — королевство рухнет.", "scenes": ["Вход в сон через ритуал шаманов", "Кошмары великана: огонь, потоп и одиночество", "Ядро сна, где бродит паразит-пожиратель снов"], "twist": "Великан просыпается в любом случае — вопрос, проснётся ли он в ярости или спокойным.", "reward": "Дружба великана, 10 000 зм, плащ снов."}, {"n": "Падение звезды", "lvl": "15–17", "hook": "Звезда упала в горах, и её свет превращает зверей в чудовищ. За осколками охотятся три державы.", "scenes": ["Гонка армий через перевал", "Кратер, где искажено время и пространство", "Сама звезда — живое существо, просящее вернуть её на небо"], "twist": "Если звезду вернут, державы лишатся оружия; если оставят — мир изменится.", "reward": "Звёздный металл, очень редкий предмет, благодарность звезды."}, {"n": "Город-корабль", "lvl": "15–17", "hook": "Летающий город-корабль терпит крушение и идёт прямо на столицу. На борту — сто тысяч жителей.", "scenes": ["Высадка на падающий город", "Мятеж в машинном отсеке", "Мостик, где капитан отказывается сменить курс"], "twist": "Курс задан нарочно — капитан мстит столице за давнюю резню.", "reward": "Город-союзник, 12 000 зм, легендарный предмет на выбор."}, {"n": "Граница мира", "lvl": "16–18", "hook": "Край мира начал рассыпаться, и туман пустоты съедает земли по миле в день.", "scenes": ["Последние деревни у тумана", "Путь по осколкам земли над бездной", "Маяк творения, где погас огонь"], "twist": "Огонь маяка нужно зажечь жизнью — одного из героев или того, кто погасил его.", "reward": "Легендарный предмет, благословение мира, титул."}, {"n": "Последний пир лича", "lvl": "16–18", "hook": "Древний лич приглашает героев на пир, обещая отдать свою филактерию — если они выдержат вечер.", "scenes": ["Пир с мёртвыми гостями и смертельными загадками", "Танец, где проигравший теряет годы жизни", "Тайная сокровищница с десятью филактериями-обманками"], "twist": "Лич устал существовать и хочет, чтобы его победили красиво.", "reward": "Филактерия, 15 000 зм, книга заклинаний лича."}, {"n": "Восстание элементалей", "lvl": "16–17", "hook": "Четыре стихии подняли бунт против призывателей, разрушая города магов.", "scenes": ["Город магов в огне и воде", "Переговоры с князем стихий на нейтральном плане", "Ритуал, который связал стихии тысячу лет назад"], "twist": "Стихии требуют свободы; их освобождение лишит мир магии призыва.", "reward": "Договор со стихиями, очень редкий предмет, 10 000 зм."}, {"n": "Сердце бездны", "lvl": "17–19", "hook": "Князь демонов проложил путь в мир через сердце уснувшего вулкана.", "scenes": ["Армия демонов у подножья", "Вход в бездну и падение в пасть", "Тронный зал князя и его истинное имя"], "twist": "Истинное имя князя записано в сердце одного из союзников героев.", "reward": "Легендарный предмет, 20 000 зм, слава."}, {"n": "Голос из колодца времён", "lvl": "17–18", "hook": "Из колодца звучит голос героя — из будущего, умоляющий не спускаться.", "scenes": ["Колодец и смыкающиеся эпохи", "Встреча с собственными будущими «я»", "Хранитель времени и сделка"], "twist": "Будущее изменится, только если один из героев останется хранителем вместо прежнего.", "reward": "Песочные часы времени (легендарные), 18 000 зм."}, {"n": "Небесный трон", "lvl": "17–20", "hook": "Небожители ищут нового владыку пустого трона и выбрали одного из героев.", "scenes": ["Испытание мудрости, силы и милосердия", "Соперник-полубог", "Коронация, которую нужно принять или отвергнуть"], "twist": "Прежний владыка жив и заточён — трон пуст из-за измены.", "reward": "Божественное благословение, легендарный предмет."}, {"n": "Пожиратель солнца", "lvl": "18–20", "hook": "Гигантский змей обвивает солнце, и мир погружается во тьму на неделю.", "scenes": ["Хаос и культы тьмы на земле", "Путь на астральный план по лучам последнего света", "Бой со змеем на поверхности солнца"], "twist": "Змея можно успокоить, вернув ему похищенное яйцо.", "reward": "Солнечный камень, 25 000 зм, вечная благодарность мира."}, {"n": "Воскрешение империи", "lvl": "18–19", "hook": "Мёртвая империя воскресла за ночь — с армиями, королём и законами тысячелетней давности.", "scenes": ["Переговоры с королём-призраком", "Война на два фронта", "Ритуал, державший империю в смерти"], "twist": "Империю вернул бог смерти, решивший исправить свою давнюю ошибку.", "reward": "Земли, титул, легендарное оружие."}, {"n": "Карта всех миров", "lvl": "18–20", "hook": "Найдена карта, ведущая на все планы бытия; за ней охотится каждый бог.", "scenes": ["Погоня через три плана за одну ночь", "Аукцион на базаре миров", "Последний хранитель карты и его выбор"], "twist": "Карту создала сама пустота, чтобы найти выход в мир.", "reward": "Карта (артефакт), 30 000 зм, друзья и враги среди богов."}, {"n": "Гибель богов", "lvl": "19–20", "hook": "Двое богов вступили в войну, и сражение их аватаров идёт в мире смертных.", "scenes": ["Поле битвы размером с королевство", "Посольство в небесный чертог", "Сам бой аватаров и шанс вмешаться"], "twist": "Войну начал третий бог, ждущий, когда оба ослабеют.", "reward": "Божественная искра, титул героя эпохи."}, {"n": "Последний дракон", "lvl": "19–20", "hook": "Древнейший дракон умирает, и его последний выдох уничтожит континент. Он просит выслушать его историю.", "scenes": ["Путь к логову через стражей", "История дракона и его тайна", "Решение — принять его силу или позволить ей уйти"], "twist": "Дракон — создатель мира; его смерть — конец старой эпохи.", "reward": "Драконье сердце (легендарный), сокровищница 50 000 зм."}, {"n": "Мятеж ангелов", "lvl": "19–20", "hook": "Легион ангелов отказался служить небесам и спустился, чтобы править смертными «ради их блага».", "scenes": ["Город под ангельским законом", "Восстание людей и ангелов-отступников", "Генерал легиона и его правда"], "twist": "Генерал прав в одном: небеса действительно оставили мир.", "reward": "Ангельский клинок (очень редкий), благодать."}, {"n": "Конец эпохи", "lvl": "20", "hook": "Все пророчества сходятся: завтра мир изменится навсегда. Герои решают, каким он станет.", "scenes": ["Совет держав и богов", "Последняя битва с тем, кто хочет остановить время", "Новый рассвет и выбор каждого героя"], "twist": "Пророчества писали сами герои — в прошлых жизнях.", "reward": "Эпилог, легендарная слава, эпический дар для каждого."}]);})();

